C++.fragment:
int parse_twice(const std::string& s) {
    return std::stoi(s) * 2;
}

Go.fragment:
func parse_twice(s string) (int, error) {
 v, err := strconv.Atoi(s)
 if err != nil { return 0, err }
 return v * 2, nil
}

Kotlin.fragment:
fun parseTwice(s: String): Int {
    val v = s.toInt()
    return v * 2
}

Swift.fragment:
enum ParseError: Error { case invalid }
func parseTwice(_ s: String) throws -> Int32 {
    guard let v = Int32(s) else { throw ParseError.invalid }
    return v * 2
}
